document.addEventListener('submit',async event=>{const form=event.target;if(!['save-course-form','card-form','exam-form','profile-form','auth-form','goal-form','quiz-config'].includes(form.id))return;event.preventDefault();const f=new FormData(form);
 if(form.id==='quiz-config'){startQuiz(form);return;}
 if(form.id==='save-course-form'){await createCourseFromScan(form);return;}
 if(form.id==='card-form'){const index=form.dataset.index;const card={q:f.get('q').trim(),a:f.get('a').trim(),source:Number(f.get('source'))};if(!card.q||!card.a)return;if(index==='')course().cards.push(card);else course().cards[Number(index)]=card;save();closeModal();render();toast('Carte enregistrée. Elle est prête à réviser.');return;}
 if(form.id==='exam-form'){const id=form.dataset.id;const date=f.get('date');if(date<=todayKey()){toast('Choisis une date à partir de demain pour répartir tes révisions.');return;}const e={id:id||'exam-'+crypto.randomUUID(),created:db.exams.find(x=>x.id===id)?.created||todayKey(),courseId:f.get('courseId'),name:f.get('name').trim(),date,minutes:Number(f.get('minutes'))};if(id)db.exams=db.exams.map(old=>old.id===id?e:old);else db.exams.push(e);save();closeModal();navigate('planning');toast('Ton planning est prêt. Une étape après l’autre.');return;}
 if(form.id==='profile-form'||form.id==='auth-form'){db.name=f.get('name').trim()||'Léa';db.level=f.get('level');db.profile=true;save();closeModal();navigate('dashboard');toast('Bienvenue dans ton espace, '+db.name+' !');return;}
 if(form.id==='goal-form'){db.goal=Number(f.get('goal'));save();closeModal();render();toast('Ton objectif suit ton rythme.');}
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='library-search'){state.query=el.value;const cs=db.courses.filter(c=>(state.filter==='Toutes'||c.subject===state.filter)&&(c.title+' '+c.chapter+' '+c.subject).toLowerCase().includes(el.value.toLowerCase()));$('#library-results').innerHTML=libraryResults(cs);}if(el.id==='global-search')renderSearch(el.value);if(el.id==='practice-answer'&&state.session)state.session.text=el.value;});
document.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-plan]')){if(el.checked&&!db.planDone.includes(el.dataset.plan))db.planDone.push(el.dataset.plan);else if(!el.checked)db.planDone=db.planDone.filter(id=>id!==el.dataset.plan);save();toast(el.checked?'Séance cochée. Un petit pas de plus.':'Séance remise à faire. À ton rythme.');}if(el.id==='file-input'||el.id==='camera-input')importFiles([...el.files]);});
document.addEventListener('focusout',event=>{const el=event.target;if(el.hasAttribute('data-summary-edit')){const c=course();c.notes??={};c.notes[state.format]??={};c.notes[state.format][el.dataset.summaryEdit]=el.textContent.trim();save();}});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();return;}if(event.key==='Escape'){closeModal();$('.sidebar')?.classList.remove('open');$('.sidebar-backdrop')?.classList.add('hidden');}if(event.key==='Tab'&&state.modal){const focusable=$$('button:not(:disabled),input,select,textarea,a[href],[tabindex="0"]',$('#modal-root')).filter(e=>e.offsetParent);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}if(event.code==='Space'&&state.route==='flashcards'&&!state.modal&&!event.target.matches('input,textarea,button')){event.preventDefault();state.session.revealed=!state.session.revealed;render();}});
function selectPlanActivity(id){state.courseId=id;openModal('Ton petit pas d’aujourd’hui.',`<p>${esc(course().title)} · À toi de choisir.</p>${activityChoice('Flashcards','Un rappel des notions essentielles','cards','green','start-cards',id)}${activityChoice('QCM','Vérifie ce qui reste en mémoire','target','purple','start-quiz',id)}${activityChoice('Page blanche','Restitue sans regarder le cours','file','blue','selected-mode',id).replace('data-id=', 'data-mode="blank" data-id=')}`);}
function openSearch(){openModal('Une idée à retrouver ?',`<div class="input-wrap">${ico('search')}<input id="global-search" placeholder="Un cours, une matière, une notion…" aria-label="Rechercher un cours" style="width:100%"></div><div id="search-results" style="margin-top:17px"></div>`);renderSearch('');}
function renderSearch(q){const matches=db.courses.filter(c=>normalize(c.title+' '+c.subject+' '+c.sections.map(s=>s.text).join(' ')).includes(normalize(q)));$('#search-results').innerHTML=matches.length?matches.map(c=>`<button class="search-result" data-course="${c.id}"><span class="tile-icon ${c.color}">${ico(c.icon)}</span><span><h3>${esc(c.title)}</h3><p>${esc(c.subject)} · ${esc(c.level)}</p></span></button>`).join(''):'<div class="empty-state" style="padding:25px"><p>Aucun cours trouvé. Essaie un autre mot.</p></div>';}
function parseSections(text){return StudyTools.sections(text);}
function makeCards(c){return StudyTools.cards(c);}
function makeQuiz(c){return StudyTools.quiz(c);}
function setupScanner(){if(state.route!=='scanner'||state.scanBusy||state.scanStep!==1)return;const dz=$('#drop-zone');if(!dz)return;dz.addEventListener('dragover',e=>{e.preventDefault();dz.classList.add('dragging');});dz.addEventListener('dragleave',()=>dz.classList.remove('dragging'));dz.addEventListener('drop',e=>{e.preventDefault();dz.classList.remove('dragging');importFiles([...e.dataTransfer.files]);});}
function loadScript(src,globalName){if(window[globalName])return Promise.resolve(window[globalName]);return new Promise((resolve,reject)=>{let script=document.createElement('script');script.src=src;script.onload=()=>resolve(window[globalName]);script.onerror=()=>{script.remove();reject(new Error('Le module de lecture n’a pas pu être chargé. Vérifie ta connexion.'));};document.head.append(script);});}
function scanProgress(p,label){state.scanProgress=p;if($('#scan-label'))$('#scan-label').textContent=label+' · '+p+' %';if($('#scan-bar'))$('#scan-bar').style.width=p+'%';}
async function importFiles(files){if(!files.length)return;const append=state.scanAppend;state.scanAppend=false;const previousText=append?state.scanText:'';const previousFiles=append?[...state.scanFiles]:[];if(files.length+previousFiles.length>12){toast('Importe au maximum 12 fichiers à la fois.');return;}if(files.some(f=>f.size>15*1024*1024)){state.scanError='Un fichier dépasse 15 Mo.';render();return;}if(files.some(f=>!f.type.startsWith('image/')&&f.type!=='application/pdf'&&!/\.(pdf|txt)$/i.test(f.name))){state.scanError='Ce format n’est pas encore pris en charge. Choisis une image, un PDF ou un fichier texte.';render();return;}state.scanBusy=true;state.scanError='';state.scanFiles=previousFiles.concat(files.map(f=>f.name));state.scanProgress=0;if(!append){scanPreviewUrls.forEach(URL.revokeObjectURL);scanPreviewUrls=[];}scanPreviewUrls.push(...files.filter(f=>f.type.startsWith('image/')).map(f=>URL.createObjectURL(f)));render();let worker=null;const texts=[];let uncertain=0;try{
 async function ocr(image,fileNo){if(!worker){await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js','Tesseract');worker=await Tesseract.createWorker('fra',1,{logger:m=>{if(m.status==='recognizing text')scanProgress(Math.round((fileNo+m.progress)/files.length*100),'Lecture du texte imprimé');}});}const result=await worker.recognize(image);uncertain+=result.data.confidence<75?1:0;let text=result.data.lines?.length?result.data.lines.map(l=>(l.confidence<60?'[à vérifier] ':'')+l.text.trim()).join('\n'):result.data.text;if(!text.trim())throw new Error('Aucun texte lisible n’a été trouvé dans une image.');return text;}
 for(let i=0;i<files.length;i++){const file=files[i];scanProgress(Math.round(i/files.length*100),'Lecture de '+file.name);if(/\.txt$/i.test(file.name)){texts.push(await file.text());continue;}if(file.type==='application/pdf'||/\.pdf$/i.test(file.name)){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js','pdfjsLib');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;if(pdf.numPages>25)throw new Error('Ce PDF contient plus de 25 pages. Sépare-le en chapitres plus courts.');for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p);const content=await page.getTextContent();let t=content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('').trim();if(t.length<30){const canvas=document.createElement('canvas'),view=page.getViewport({scale:1.5});canvas.width=view.width;canvas.height=view.height;await page.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;t=await ocr(canvas,i);}texts.push('Page '+p+' — '+file.name+'\n'+t);}}else{const image=await prepareScanImage(file);try{texts.push(await ocr(image,i));}finally{image.width=0;image.height=0;}}}
 state.scanText=[previousText,...texts].filter(Boolean).join('\n\n');if(state.scanText.trim().length<40)throw new Error('Le texte détecté est trop court pour créer un cours.');if(!append){const meta=StudyTools.metadata(state.scanText,files[0].name);state.scanTitle=meta.title;state.scanSubject=meta.subject;}state.scanStep=2;state.scanBusy=false;render();toast(uncertain?'Lecture partielle : vérifie les passages signalés avant de continuer.':'Texte extrait. Prends un moment pour vérifier la transcription.');
 }catch(error){state.scanBusy=false;state.scanError=/^(Le |La |Ce |Un |Aucun |Les )/.test(error.message||'')?error.message:'Le document n’a pas pu être lu. Essaie une image JPG ou PNG bien éclairée, ou un autre PDF.';state.scanText=[previousText,...texts].filter(Boolean).join('\n\n');render();}finally{if(worker)await worker.terminate();}}
let recognition;
function dictate(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('La dictée n’est pas disponible dans ce navigateur. Tu peux écrire ton explication.');return;}if(recognition){recognition.stop();recognition=null;return;}recognition=new Speech();recognition.lang='fr-FR';recognition.continuous=true;recognition.interimResults=false;recognition.onresult=e=>{const t=Array.from(e.results).slice(e.resultIndex).map(r=>r[0].transcript).join(' ');if($('#practice-answer')){$('#practice-answer').value+=' '+t;state.session.text=$('#practice-answer').value;}};recognition.onerror=e=>{toast(e.error==='not-allowed'?'Autorise le microphone dans ton navigateur, ou écris ton explication.':'La dictée s’est arrêtée. Tu peux continuer à l’écrit.');};recognition.onend=()=>{recognition=null;if($('#speech-status'))$('#speech-status').textContent='Dictée terminée.';};try{recognition.start();$('#speech-status').textContent='Je t’écoute… Clique à nouveau pour arrêter.';}catch{recognition=null;toast('La dictée n’a pas pu démarrer. Continue à l’écrit.');}}
async function exportPdf(){const c=course();toast('Préparation de ta fiche PDF…');try{await loadScript('/revizz/assets/jspdf.umd.min.js','jspdf');const pdf=new jspdf.jsPDF();const fontBytes=new Uint8Array(await (await fetch('/revizz/assets/NotoSans-Regular.ttf')).arrayBuffer());let fontBinary='';for(let k=0;k<fontBytes.length;k+=16384)fontBinary+=String.fromCharCode(...fontBytes.subarray(k,k+16384));pdf.addFileToVFS('Revizz.ttf',btoa(fontBinary));pdf.addFont('Revizz.ttf','NotoSans','normal');pdf.addFont('Revizz.ttf','NotoSans','bold');let y=22;pdf.setTextColor(119,85,214);pdf.setFont('NotoSans','bold');pdf.setFontSize(23);pdf.text('revizz.',18,y);y+=13;pdf.setTextColor(40,39,59);pdf.setFontSize(17);const title=pdf.splitTextToSize(c.title,174);pdf.text(title,18,y);y+=title.length*8;pdf.setFontSize(9);pdf.setFont('NotoSans','normal');pdf.setTextColor(125,120,140);pdf.text(`${c.subject} | ${c.level} | ${state.format==='express'?'Résumé express':state.format==='last'?'Dernière minute':'Fiche complète'}`,18,y);y+=14;for(let i=0;i<c.sections.length;i++){const section=c.sections[i];const text=StudyTools.summaryText(c,state.format,i);if(y>250){pdf.addPage();y=22;}pdf.setTextColor(119,85,214);pdf.setFont('NotoSans','bold');pdf.setFontSize(12);const head=pdf.splitTextToSize(section.title,174);pdf.text(head,18,y);y+=head.length*6+4;pdf.setFont('NotoSans','normal');pdf.setTextColor(55,50,65);pdf.setFontSize(10);const lines=pdf.splitTextToSize(text,174);for(const line of lines){if(y>273){pdf.addPage();y=22;}pdf.text(line,18,y);y+=5.5;}y+=5;pdf.setTextColor(150,140,165);pdf.setFontSize(8);pdf.text('Source : cours vérifié, passage '+(i+1),18,y);y+=13;}for(let i=1;i<=pdf.getNumberOfPages();i++){pdf.setPage(i);pdf.setFontSize(8);pdf.setTextColor(160);pdf.text('Revizz — Tes cours deviennent tes meilleurs outils de révision.',18,288);pdf.text(`${i} / ${pdf.getNumberOfPages()}`,180,288);}pdf.save(`Revizz-${c.title.replace(/[^a-zA-ZÀ-ÿ0-9 -]/g,'')}.pdf`);toast('Ta fiche PDF est prête. Bonne révision !');}catch{toast('Le PDF n’a pas pu être créé. Vérifie ta connexion et réessaie.');}}
